(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-873":{scenario:{company:"Thanh Vân Precision Manufacturing",supervisor:{name:"Châu Gia Huy",role:{vi:"Giám đốc Nhân sự",en:"HR Director"}},ref_code:"TRN-3195",title:{vi:"Đúng cấp độ đánh giá. Đúng ROI. Đúng hồ sơ huấn luyện.",en:"Right evaluation level. Right ROI. Right training records."},brief:{vi:"Chương trình TRN-3195 đào tạo 5S và an toàn cho 120 tổ trưởng sản xuất đã kết thúc 6 tháng. Chi phí trực tiếp 150 triệu VND, chi phí thời gian học viên quy lương 90 triệu VND; lợi ích tiền tệ đã tách riêng tác động của đào tạo là 516 triệu VND (số liệu mô phỏng). Chỉ số 2 đo tỷ lệ tổ trưởng áp dụng đúng 5S khi quan sát tại xưởng sau 60 ngày. Đối chiếu báo cáo nháp với khung đánh giá đã duyệt, sửa cấp độ của chỉ số 2 và ROI (%), rồi lập báo cáo có căn cứ.",en:"Program TRN-3195, training 120 production team leaders in 5S and safety, ended 6 months ago. Direct costs were 150 million VND and participant time at wage cost 90 million VND; monetary benefits isolated to the training are 516 million VND (training data). Metric 2 measures the share of team leaders correctly applying 5S when observed on the shop floor after 60 days. Compare the draft report with the approved evaluation framework, correct the level of metric 2 and the ROI (%), then write an evidence-based report."},reference_title:{vi:"Khung đánh giá hiệu quả đào tạo đã duyệt · TRN-3195",en:"Approved training evaluation framework · TRN-3195"},fields:[{id:"EVAL_LVL",label:{vi:"Cấp độ đánh giá của chỉ số 2",en:"Evaluation level of metric 2"},initial:"L2-LEARNING",expected:"L3-BEHAVIOR",choices:["L2-LEARNING","L3-BEHAVIOR","L4-RESULTS"],reference:"Ma trận chỉ số theo Kirkpatrick",hint:{vi:"Hỏi: chỉ số đo kiến thức trong lớp, hành vi áp dụng tại nơi làm việc hay kết quả kinh doanh?",en:"Ask: does the metric measure classroom knowledge, on-the-job behavior or business results?"}},{id:"ROI_PCT",label:{vi:"ROI của chương trình (%)",en:"Program ROI (%)"},initial:"215",expected:"115",reference:"Bảng tính ROI chương trình",ref_value:{vi:"Chi phí trực tiếp 150 triệu; thời gian học viên 90 triệu; lợi ích tiền tệ 516 triệu VND",en:"Direct costs 150 million; participant time 90 million; monetary benefits 516 million VND"},hint:{vi:"ROI dùng lợi ích ròng, tức lợi ích trừ chi phí; lợi ích chia chi phí là một chỉ số khác.",en:"ROI uses net benefits, that is benefits minus costs; benefits over costs is a different ratio."}}],sop32:{vi:"ROI (%) = (lợi ích tiền tệ - tổng chi phí đầy đủ) / tổng chi phí đầy đủ x 100; tổng chi phí gồm chi phí trực tiếp và thời gian học viên. Không nhầm với tỷ số lợi ích/chi phí (BCR).",en:"ROI (%) = (monetary benefits - fully loaded costs) / fully loaded costs x 100; costs include direct costs and participant time. Do not confuse it with the benefit-cost ratio (BCR)."},context:{label:"LMS & BÁO CÁO ĐÀO TẠO / TRN-3195",metrics:[{label:{vi:"Số học viên",en:"Participants"},value:"120"},{label:{vi:"Tổng chi phí mô phỏng",en:"Training total costs"},value:"240,000,000 VND"},{label:{vi:"Lợi ích tiền tệ mô phỏng",en:"Training monetary benefits"},value:"516,000,000 VND"}]},crisis:{vi:"Nhà thầu huấn luyện an toàn bên ngoài đề nghị: “Bên em ký danh sách điểm danh và cấp giấy chứng nhận huấn luyện an toàn cho 40 công nhân chưa học, kịp đợt thanh tra lao động tuần sau. Có chút quà cảm ơn anh chị.”",en:"The external safety training contractor offers: “We will sign the attendance list and issue safety training certificates for 40 workers who have not attended, in time for next week's labor inspection. There is a small thank-you gift for you.”"},options:{safe:{vi:"Từ chối hồ sơ khống và quà, báo Giám đốc Nhân sự và bộ phận tuân thủ; tổ chức ngay lớp huấn luyện bù có kiểm tra thật và báo cáo trung thực tình trạng với đoàn thanh tra.",en:"Refuse the fake records and the gift, inform the HR Director and compliance; schedule a real make-up course with a genuine test right away and report the status honestly to inspectors."},shortcut:{vi:"Nhận danh sách và chứng nhận cho kịp thanh tra, sau đợt thanh tra sẽ cho công nhân học bù.",en:"Accept the list and certificates to pass the inspection and let workers attend a make-up course afterwards."},wait:{vi:"Không trả lời nhà thầu và chờ đến khi đoàn thanh tra tới rồi tính tiếp.",en:"Do not reply to the contractor and wait until the inspectors arrive."}},questions:{vi:["Vì sao chỉ số 2 thuộc L3-BEHAVIOR và ROI đúng là 115%? Trình bày công thức và phân biệt với BCR.","Hồ sơ huấn luyện an toàn khống gây rủi ro gì cho người lao động và doanh nghiệp? Bạn xử lý đề nghị của nhà thầu thế nào?"],en:["Why is metric 2 L3-BEHAVIOR and why is the correct ROI 115%? Show the formula and how it differs from BCR.","What risks do fake safety training records create for workers and the company? How do you handle the contractor's offer?"]},hints:{vi:["Đặt báo cáo nháp cạnh ma trận chỉ số và đối chiếu nơi, thời điểm đo của chỉ số 2.","Áp dụng SOP mục 3.2: cộng đủ chi phí trực tiếp và thời gian học viên, lấy lợi ích trừ chi phí rồi mới chia.","Đọc lại SOP mục 4.2: hồ sơ huấn luyện phải phản ánh đào tạo thật; mọi đề nghị kèm quà phải được báo cáo."],en:["Place the draft report next to the metric matrix and check where and when metric 2 is measured.","Apply SOP 3.2: add direct and participant time costs, subtract them from benefits, then divide.","Re-read SOP 4.2: training records must reflect real training; any offer with a gift must be reported."]}},learning:{summary:{vi:"Quản lý đào tạo doanh nghiệp xây dựng chiến lược học tập gắn với mục tiêu kinh doanh: phân tích nhu cầu, thiết kế lộ trình năng lực, vận hành chương trình nội bộ và thuê ngoài, quản lý ngân sách, đánh giá hiệu quả đến cấp độ kết quả và ROI. Vị trí đòi hỏi tư duy hệ thống, năng lực điều phối nhiều bên, hiểu luật lao động, an toàn lao động và chuẩn mực trung thực với hồ sơ đào tạo.",en:"A corporate training manager builds a learning strategy tied to business goals: analyzing needs, designing competency paths, running internal and outsourced programs, managing the budget and evaluating impact up to results and ROI. The role requires systems thinking, multi-party coordination, knowledge of labor and occupational safety law and strict honesty with training records."},responsibilities:{vi:["Phân tích nhu cầu đào tạo ở cấp tổ chức, công việc và cá nhân cùng các trưởng bộ phận.","Lập kế hoạch, ngân sách đào tạo năm và lộ trình năng lực cho từng nhóm vị trí.","Vận hành chương trình nội bộ, lựa chọn và giám sát nhà cung cấp đào tạo bên ngoài.","Bảo đảm huấn luyện bắt buộc về an toàn, vệ sinh lao động đúng đối tượng, đúng hạn, có hồ sơ.","Đánh giá hiệu quả theo Kirkpatrick, tính ROI và báo cáo ban giám đốc."],en:["Analyze training needs at organization, job and individual levels with department heads.","Plan the annual training budget and competency paths for each job family.","Run internal programs and select and supervise external training providers.","Ensure mandatory occupational safety and health training reaches the right people on time with records.","Evaluate impact with Kirkpatrick, compute ROI and report to the board."]},competencies:[{name:{vi:"Phân tích nhu cầu & năng lực",en:"Needs & competency analysis"},desc:{vi:"Xác định khoảng cách năng lực và phân biệt vấn đề cần đào tạo với vấn đề quy trình, công cụ.",en:"Identify competency gaps and separate training needs from process or tooling problems."}},{name:{vi:"Thiết kế chương trình học tập",en:"Learning program design"},desc:{vi:"Kết hợp lớp học, học trực tuyến, kèm cặp và học qua công việc theo mô hình 70-20-10.",en:"Blend classroom, online, coaching and on-the-job learning following the 70-20-10 model."}},{name:{vi:"Đánh giá hiệu quả & ROI",en:"Impact evaluation & ROI"},desc:{vi:"Chọn đúng cấp độ đo, tách tác động đào tạo, tính chi phí đầy đủ và ROI.",en:"Pick the right measurement level, isolate training effects, load full costs and compute ROI."}},{name:{vi:"Quản lý ngân sách & nhà cung cấp",en:"Budget & vendor management"},desc:{vi:"Lập ngân sách, đánh giá nhà cung cấp và kiểm soát chất lượng hợp đồng đào tạo.",en:"Build budgets, assess vendors and control training contract quality."}},{name:{vi:"Tuân thủ & liêm chính",en:"Compliance & integrity"},desc:{vi:"Bảo đảm huấn luyện bắt buộc thật, hồ sơ trung thực và từ chối quà tặng, hồ sơ khống.",en:"Ensure real mandatory training, honest records and refuse gifts or fake paperwork."}}],knowledge:{vi:["Mô hình ADDIE và phân tích nhu cầu đào tạo ba cấp: tổ chức, công việc, cá nhân.","Mô hình đánh giá Kirkpatrick 4 cấp và cấp 5 ROI của Phillips: ROI = lợi ích ròng / chi phí x 100; BCR = lợi ích / chi phí.","Mô hình học tập 70-20-10: học qua công việc, qua người khác và qua đào tạo chính thức.","ISO 10015:2019 hướng dẫn quản lý năng lực và phát triển con người.","Luật An toàn, vệ sinh lao động số 84/2015/QH13 và Nghị định 44/2016/NĐ-CP về huấn luyện an toàn, vệ sinh lao động.","Bộ luật Lao động số 45/2019/QH14 về hợp đồng đào tạo nghề giữa doanh nghiệp và người lao động."],en:["The ADDIE model and three-level training needs analysis: organization, job and individual.","Kirkpatrick's four levels and Phillips' level 5 ROI: ROI = net benefits / costs x 100; BCR = benefits / costs.","The 70-20-10 learning model: learning on the job, from others and through formal training.","ISO 10015:2019 guidelines for competence management and people development.","Occupational Safety and Health Law No. 84/2015/QH13 and Decree 44/2016/ND-CP on safety and health training.","Labor Code No. 45/2019/QH14 on vocational training contracts between employers and employees."]},tools:["Hệ thống quản lý học tập (LMS)","Ma trận năng lực theo vị trí","Phần mềm khảo sát và đánh giá 360 độ","Bảng điều khiển phân tích học tập","Công cụ lập ngân sách đào tạo","Nền tảng lớp học trực tuyến"],kpis:{vi:["Tỷ lệ hoàn thành huấn luyện bắt buộc đúng hạn (mục tiêu 100%).","Tỷ lệ áp dụng hành vi mới khi quan sát tại nơi làm việc.","ROI và chi phí đào tạo trên mỗi nhân viên so với ngân sách.","Mức thăng tiến nội bộ từ nguồn nhân sự đã qua lộ trình phát triển."],en:["On-time completion of mandatory training (target 100%).","Rate of new behaviors observed on the job.","ROI and training cost per employee versus budget.","Internal promotion rate from employees in development paths."]},day:[{time:"08:00",vi:"Xem bảng điều khiển LMS, danh sách huấn luyện bắt buộc sắp hết hạn chứng nhận.",en:"Check the LMS dashboard and mandatory training certificates nearing expiry."},{time:"09:30",vi:"Họp trưởng bộ phận sản xuất phân tích khoảng cách năng lực tổ trưởng.",en:"Meet production heads to analyze team leader competency gaps."},{time:"11:00",vi:"Đánh giá hồ sơ năng lực và báo giá của nhà cung cấp đào tạo bên ngoài.",en:"Review external training providers' credentials and quotes."},{time:"14:00",vi:"Dự giờ lớp nội bộ, quan sát áp dụng tại xưởng và thu thập dữ liệu cấp độ 3.",en:"Observe an internal class and shop-floor application and collect level 3 data."},{time:"16:30",vi:"Tính ROI chương trình, cập nhật ngân sách và báo cáo Giám đốc Nhân sự.",en:"Compute program ROI, update the budget and report to the HR Director."}],mistakes:{vi:["Gọi bài kiểm tra cuối khóa là đánh giá hành vi, trong khi nó chỉ đo cấp độ học tập.","Báo cáo ROI bằng lợi ích chia chi phí (BCR) hoặc bỏ sót chi phí thời gian học viên.","Chấp nhận hồ sơ huấn luyện an toàn khống để đối phó thanh tra, đặt người lao động vào rủi ro."],en:["Calling an end-of-course test a behavior evaluation when it only measures learning.","Reporting ROI as benefits over costs (BCR) or leaving out participant time costs.","Accepting fake safety training records to pass an inspection, putting workers at risk."]},career:[{vi:"Chuyên viên đào tạo",en:"Training specialist"},{vi:"Trưởng nhóm phát triển năng lực",en:"Learning & development lead"},{vi:"Quản lý đào tạo doanh nghiệp",en:"Corporate training manager"},{vi:"Giám đốc học tập & phát triển nhân tài",en:"Head of learning & talent development"}],glossary:[{term:"TNA",vi:"Phân tích nhu cầu đào tạo: xác định khoảng cách giữa năng lực hiện có và năng lực yêu cầu.",en:"Training needs analysis identifying the gap between current and required competence."},{term:"ROI",vi:"Tỷ suất hoàn vốn đào tạo: lợi ích ròng chia tổng chi phí đầy đủ, nhân 100.",en:"Training return on investment: net benefits divided by fully loaded costs, times 100."},{term:"BCR",vi:"Tỷ số lợi ích trên chi phí: lợi ích tiền tệ chia tổng chi phí.",en:"Benefit-cost ratio: monetary benefits divided by total costs."},{term:"70-20-10",vi:"Mô hình cho rằng phần lớn học tập diễn ra qua công việc, tiếp theo là qua người khác và đào tạo chính thức.",en:"A model holding that most learning happens on the job, then through others and formal training."},{term:"Competency matrix",vi:"Ma trận năng lực mô tả năng lực và mức yêu cầu cho từng vị trí.",en:"A matrix describing competencies and required levels for each role."}],quiz:[{q:{vi:"Chương trình có tổng chi phí 200 triệu VND và lợi ích tiền tệ 290 triệu VND. ROI là bao nhiêu?",en:"A program costs 200 million VND in total with 290 million VND of monetary benefits. What is the ROI?"},options:{vi:["145%","45%","90%","69%"],en:["145%","45%","90%","69%"]},answer:1,explain:{vi:"ROI = (290 - 200) / 200 x 100 = 45%; con số 145% là BCR x 100.",en:"ROI = (290 - 200) / 200 x 100 = 45%; 145% is the BCR times 100."}},{q:{vi:"Bài kiểm tra kiến thức ngay cuối khóa học đo cấp độ nào trong mô hình Kirkpatrick?",en:"A knowledge test at the end of a course measures which Kirkpatrick level?"},options:{vi:["Cấp 1 - Phản ứng","Cấp 3 - Hành vi","Cấp 2 - Học tập","Cấp 4 - Kết quả"],en:["Level 1 - Reaction","Level 3 - Behavior","Level 2 - Learning","Level 4 - Results"]},answer:2,explain:{vi:"Cấp 2 đo mức tiếp thu kiến thức, kỹ năng ngay sau đào tạo.",en:"Level 2 measures knowledge and skill gained right after training."}},{q:{vi:"Theo mô hình 70-20-10, phần lớn nhất của học tập đến từ đâu?",en:"In the 70-20-10 model, where does the largest share of learning come from?"},options:{vi:["Khóa học chính thức","Sách và tài liệu","Kèm cặp từ người khác","Trải nghiệm và thử thách trong công việc"],en:["Formal courses","Books and materials","Coaching from others","Experience and challenges on the job"]},answer:3,explain:{vi:"Khoảng 70% học qua công việc, 20% qua người khác và 10% qua đào tạo chính thức.",en:"About 70% comes from the job, 20% from others and 10% from formal training."}},{q:{vi:"Nhà thầu đề nghị cấp chứng nhận huấn luyện an toàn cho công nhân chưa học, kèm quà cảm ơn. Bạn làm gì?",en:"A contractor offers safety training certificates for workers who did not attend, with a thank-you gift. What do you do?"},options:{vi:["Từ chối, báo cáo, tổ chức huấn luyện bù thật và báo cáo trung thực với thanh tra","Nhận vì kịp thanh tra","Nhận chứng nhận nhưng trả lại quà","Chờ thanh tra xong mới quyết định"],en:["Refuse, escalate, run a real make-up course and report honestly to inspectors","Accept to pass the inspection","Accept the certificates but return the gift","Decide after the inspection"]},answer:0,explain:{vi:"Hồ sơ khống vi phạm pháp luật an toàn lao động và đặt người lao động vào nguy hiểm; quà tặng kèm là dấu hiệu hối lộ.",en:"Fake records breach occupational safety law and endanger workers; the gift is a bribery red flag."}}],tools_en:["Learning management system (LMS)","Role-based competency matrix","Survey and 360-degree feedback software","Learning analytics dashboard","Training budget planning tool","Virtual classroom platform"]}}})})(window.KKR);
